WITH base AS (SELECT *, CONCAT(location, ' ', dept_name) AS location_dept_name FROM departments WHERE location IN ('Berlin', 'London') AND (location = 'London' OR budget BETWEEN 2779000 AND 2864000)), departments_stats AS (SELECT dept_name, ROUND((100 * SUM(CASE WHEN dept_name = 'Legal' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_legal FROM base GROUP BY dept_name) SELECT dept_name, pct_legal FROM departments_stats WHERE pct_legal > 25 ORDER BY dept_name
